/**
 * Finnomena brand CSS custom properties — for projects that want
 * Finnomena's colors/typography/spacing WITHOUT installing
 * @coinbase/cds-web or using CDS React components.
 *
 * PROVENANCE: not hand-guessed. These are the REAL, byte-exact values
 * produced by running @coinbase/cds-web@9.26.1's own `createThemeCssVars()`
 * against `createNeonTheme()`'s output (light and dark, resolved), captured
 * via a scratch project this session. The variable naming
 * (`--{category}-{key}`, e.g. `--color-fg`, `--space-2`,
 * `--borderRadius-200`, `--fontFamily-body`) matches exactly what real
 * CDS's ThemeProvider emits at runtime — confirmed by inspecting
 * `esm/core/createThemeCssVars.js` and `styleVarPrefixes` directly, not
 * guessed. This means a project that starts here and later adopts full CDS
 * (see ${CLAUDE_PLUGIN_ROOT}/skills/neon-create) needs ZERO CSS rework —
 * the same `var(--color-fg)` references keep working, now driven by
 * ThemeProvider instead of this static stylesheet.
 *
 * HAND-WRITTEN — NOT auto-generated by the token pipeline (that pipeline
 * can't import ${CLAUDE_PLUGIN_ROOT}/theme/cds/color-overrides.ts,
 * a real .ts file with a human-reviewed color decision). Regenerate by hand
 * when ${CLAUDE_PLUGIN_ROOT}/theme/cds/theme.config.ts's
 * `neonTheme` or
 * ${CLAUDE_PLUGIN_ROOT}/theme/cds/color-overrides.ts's
 * `colorOverrides` change (same scratch-project technique used to produce
 * this file originally).
 *
 * SCOPE: only color, typography (fontFamily/fontSize/fontWeight/
 * lineHeight), space, and borderRadius are included — the fields Finnomena
 * actually has brand data for. Raw spectrum primitives (--blue60 etc.),
 * illustration colors, and fields with no Finnomena data at all (iconSize,
 * avatarSize, controlSize, borderWidth, textTransform, shadow,
 * fontFamilyMono) are deliberately omitted — app code should reference
 * semantic tokens (--color-fg, not a raw spectrum step), and CDS's generic
 * Coinbase defaults for untouched fields don't belong in a "Finnomena"
 * branded file. The one exception to the CDS capture is the provisional
 * --layout-* group, copied by hand from the breakpoint token export (see
 * its own comment below).
 *
 * COLOR IS PROVISIONAL — see
 * ${CLAUDE_PLUGIN_ROOT}/theme/cds/color-overrides.ts's own
 * header for the full list of judgment calls made mapping Finnomena's brand
 * roles onto these slugs. Treat as first-pass, not final design sign-off.
 *
 * DARK MODE: applies automatically via `prefers-color-scheme: dark`, with
 * a `[data-theme="dark"]` attribute as a manual override (put
 * `data-theme="dark"` on <html> to force dark regardless of OS setting, or
 * `data-theme="light"` to force light). Swap this convention for your
 * project's own dark-mode mechanism (a `.dark` class, etc.) if it already
 * has one — this is a default assumption, not verified against any
 * specific target project.
 *
 * USAGE: copy this file into your project (e.g. src/theme/theme.css) and
 * import it once (e.g. in your root CSS or main entry file):
 *   import "./theme/theme.css";
 * Then reference values as var(--color-fg), var(--space-2), etc.
 *
 * TIERS:
 *   - Colors only: use only the --color-* variables below.
 *   - Colors + typography: also use --fontFamily-*, --fontSize-*,
 *     --fontWeight-*, --lineHeight-*, --space-*, --borderRadius-*.
 *   - Full CDS: don't use this file — see
 *     ${CLAUDE_PLUGIN_ROOT}/skills/neon-create instead (ThemeProvider +
 *     createNeonTheme() + real CDS components).
 */

:root {
  /* --- Colors (light — default) --- */
  --color-currentColor: currentColor;
  --color-transparent: rgba(255, 255, 255, 0);

  --color-fg: rgba(0, 0, 0, 0.851);
  --color-fgMuted: rgba(0, 0, 0, 0.651);
  --color-fgInverse: rgb(255, 255, 255);
  --color-fgPrimary: rgb(1, 23, 43);
  --color-fgWarning: rgb(242, 100, 20);
  --color-fgPositive: rgb(0, 150, 70);
  --color-fgNegative: rgb(214, 8, 8);

  --color-bg: rgb(255, 255, 255);
  --color-bgAlternate: rgb(242, 242, 242);
  --color-bgInverse: rgb(0, 0, 0);
  --color-bgOverlay: rgba(0, 0, 0, 0.2);
  --color-bgElevation1: rgb(255, 255, 255);
  --color-bgElevation2: rgb(255, 255, 255);
  --color-bgPrimary: rgb(1, 23, 43);
  --color-bgPrimaryWash: rgb(242, 243, 244);
  --color-bgSecondary: rgb(242, 242, 242);
  --color-bgTertiary: rgb(255, 255, 255);
  --color-bgSecondaryWash: rgb(247, 248, 249);
  --color-bgNegative: rgb(214, 8, 8);
  --color-bgNegativeWash: rgb(255, 245, 245);
  --color-bgPositive: rgb(0, 173, 80);
  --color-bgPositiveWash: rgb(230, 253, 240);
  --color-bgWarning: rgb(242, 100, 20);
  --color-bgWarningWash: rgb(254, 247, 243);

  --color-bgLine: rgba(0, 0, 0, 0.051);
  --color-bgLineHeavy: rgba(91, 97, 110, 0.66);
  --color-bgLineInverse: rgb(255, 255, 255);
  --color-bgLinePrimary: rgb(105, 104, 239);
  --color-bgLinePrimarySubtle: rgb(115, 162, 255);

  --color-accentSubtleRed: rgb(255, 245, 245);
  --color-accentBoldRed: rgb(247, 50, 50);
  --color-accentSubtleGreen: rgb(230, 253, 240);
  --color-accentBoldGreen: rgb(0, 231, 107);
  --color-accentSubtleBlue: rgb(246, 253, 255);
  --color-accentBoldBlue: rgb(80, 207, 255);
  --color-accentSubtlePurple: rgb(251, 246, 252);
  --color-accentBoldPurple: rgb(170, 70, 195);
  --color-accentSubtleYellow: rgb(254, 255, 245);
  --color-accentBoldYellow: rgb(242, 249, 60);
  --color-accentSubtleGray: rgb(242, 243, 244);
  --color-accentBoldGray: rgb(1, 23, 43);

  /* --- Typography (mode-independent) --- */
  --fontFamily-display1: 'IBM Plex Sans Thai', sans-serif;
  --fontFamily-display2: 'IBM Plex Sans Thai', sans-serif;
  --fontFamily-display3: 'IBM Plex Sans Thai', sans-serif;
  --fontFamily-title1: 'IBM Plex Sans Thai', sans-serif;
  --fontFamily-title2: 'IBM Plex Sans Thai', sans-serif;
  --fontFamily-title3: 'IBM Plex Sans Thai', sans-serif;
  --fontFamily-title4: 'IBM Plex Sans Thai', sans-serif;
  --fontFamily-headline: 'IBM Plex Sans Thai', sans-serif;
  --fontFamily-body: 'IBM Plex Sans Thai', sans-serif;
  --fontFamily-label1: 'IBM Plex Sans Thai', sans-serif;
  --fontFamily-label2: 'IBM Plex Sans Thai', sans-serif;
  --fontFamily-caption: 'IBM Plex Sans Thai', sans-serif;
  --fontFamily-legal: 'IBM Plex Sans Thai', sans-serif;

  --fontSize-display1: 92px;
  --fontSize-display2: 60px;
  --fontSize-display3: 54px;
  --fontSize-title1: 28px;
  --fontSize-title2: 22px;
  --fontSize-title3: 20px;
  --fontSize-title4: 1.25rem;
  --fontSize-headline: 17px;
  --fontSize-body: 17px;
  --fontSize-label1: 0.875rem;
  --fontSize-label2: 0.875rem;
  --fontSize-caption: 0.8125rem;
  --fontSize-legal: 0.8125rem;

  --fontWeight-display1: 400;
  --fontWeight-display2: 400;
  --fontWeight-display3: 700;
  --fontWeight-title1: 400;
  --fontWeight-title2: 400;
  --fontWeight-title3: 400;
  --fontWeight-title4: 400;
  --fontWeight-headline: 500;
  --fontWeight-body: 400;
  --fontWeight-label1: 600;
  --fontWeight-label2: 400;
  --fontWeight-caption: 600;
  --fontWeight-legal: 400;

  --lineHeight-display1: 102px;
  --lineHeight-display2: 70px;
  --lineHeight-display3: 64px;
  --lineHeight-title1: 34px;
  --lineHeight-title2: 28px;
  --lineHeight-title3: 25px;
  --lineHeight-title4: 1.75rem;
  --lineHeight-headline: 22px;
  --lineHeight-body: 22px;
  --lineHeight-label1: 1.25rem;
  --lineHeight-label2: 1.25rem;
  --lineHeight-caption: 1rem;
  --lineHeight-legal: 1rem;

  /* --- Spacing (mode-independent) --- */
  --space-0: 0px;
  --space-0_25: 2px;
  --space-0_5: 4px;
  --space-0_75: 6px;
  --space-1: 8px;
  --space-1_5: 12px;
  --space-2: 16px;
  --space-3: 24px;
  --space-4: 32px;
  --space-5: 40px;
  --space-6: 48px;
  --space-7: 56px;
  --space-8: 64px;
  --space-9: 72px;
  --space-10: 80px;

  /* --- Border radius (mode-independent) --- */
  --borderRadius-0: 0px;
  --borderRadius-100: 4px;
  --borderRadius-200: 8px;
  --borderRadius-300: 12px;
  --borderRadius-400: 16px;
  --borderRadius-500: 24px;
  --borderRadius-600: 32px;
  --borderRadius-700: 40px;
  --borderRadius-800: 48px;
  --borderRadius-900: 56px;
  --borderRadius-1000: 100000px;

  /* --- Layout (mode-independent) ---
   * PROVISIONAL: the Immersive pages' shared content column, copied by hand
   * from theme/tokens/breakpoint.json's Immersive Layout ("Content View
   * max-width" at xxxl_1440px; "End margins" from sm_320px). Not a CDS field
   * and nothing regenerates it. The end margin widens below. */
  --layout-contentMaxWidth: 1440px;
  --layout-endMargin: 16px;
}

/* "End margins" from the xxxl_1440px tier's Viewport min-width. */
@media (min-width: 1440px) {
  :root {
    --layout-endMargin: 24px;
  }
}

/* --- Colors (dark) — OS preference --- */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme='light']) {
    --color-fg: rgb(255, 255, 255);
    --color-fgMuted: rgba(255, 255, 255, 0.651);
    --color-fgInverse: rgba(0, 0, 0, 0.851);
    --color-fgPrimary: rgb(230, 232, 234);
    --color-fgNegative: rgb(243, 9, 9);
    --color-fgPositive: rgb(0, 196, 91);

    --color-bg: rgb(0, 0, 0);
    --color-bgAlternate: rgb(26, 26, 26);
    --color-bgInverse: rgb(255, 255, 255);
    --color-bgOverlay: rgba(0, 0, 0, 0.502);
    --color-bgElevation1: rgb(26, 26, 26);
    --color-bgElevation2: rgb(51, 51, 51);
    --color-bgPrimary: rgb(65, 81, 96);
    --color-bgPrimaryWash: rgb(1, 23, 43);
    --color-bgSecondary: rgb(26, 26, 26);
    --color-bgTertiary: rgb(38, 38, 38);
    --color-bgSecondaryWash: rgb(20, 21, 25);
    --color-bgNegative: rgb(243, 9, 9);
    --color-bgNegativeWash: rgb(51, 0, 4);
    --color-bgPositiveWash: rgb(0, 31, 18);
    --color-bgWarningWash: rgb(51, 13, 0);

    --color-bgLine: rgba(255, 255, 255, 0.149);
    --color-bgLineHeavy: rgba(138, 145, 158, 0.66);
    --color-bgLineInverse: rgb(0, 0, 0);
    --color-bgLinePrimarySubtle: rgb(5, 59, 177);

    --color-transparent: rgba(0, 0, 0, 0);
  }
}

/* --- Colors (dark) — manual override via data-theme="dark" --- */
:root[data-theme='dark'] {
  --color-fg: rgb(255, 255, 255);
  --color-fgMuted: rgba(255, 255, 255, 0.651);
  --color-fgInverse: rgba(0, 0, 0, 0.851);
  --color-fgPrimary: rgb(230, 232, 234);
  --color-fgNegative: rgb(243, 9, 9);
  --color-fgPositive: rgb(0, 196, 91);

  --color-bg: rgb(0, 0, 0);
  --color-bgAlternate: rgb(26, 26, 26);
  --color-bgInverse: rgb(255, 255, 255);
  --color-bgOverlay: rgba(0, 0, 0, 0.502);
  --color-bgElevation1: rgb(26, 26, 26);
  --color-bgElevation2: rgb(51, 51, 51);
  --color-bgPrimary: rgb(65, 81, 96);
  --color-bgPrimaryWash: rgb(1, 23, 43);
  --color-bgSecondary: rgb(26, 26, 26);
  --color-bgTertiary: rgb(38, 38, 38);
  --color-bgSecondaryWash: rgb(20, 21, 25);
  --color-bgNegative: rgb(243, 9, 9);
  --color-bgNegativeWash: rgb(51, 0, 4);
  --color-bgPositiveWash: rgb(0, 31, 18);
  --color-bgWarningWash: rgb(51, 13, 0);

  --color-bgLine: rgba(255, 255, 255, 0.149);
  --color-bgLineHeavy: rgba(138, 145, 158, 0.66);
  --color-bgLineInverse: rgb(0, 0, 0);
  --color-bgLinePrimarySubtle: rgb(5, 59, 177);

  --color-transparent: rgba(0, 0, 0, 0);
}

/* Neon base adapter: shadcn/ui's slots alias Neon roles from theme.css, so
 * light and dark both come from theme.css alone. Imported by src/index.css
 * after Tailwind; theme.css is the canonical CSS adapter, copied as-is. */
@import "./theme.css";

/* Components use Neon roles, never dark: classes; the variant exists only for
 * code that already has them. AppRoot sets data-theme on <html>. */
@custom-variant dark (&:where([data-theme="dark"], [data-theme="dark"] *));

@theme inline {
  --font-sans: var(--fontFamily-body);

  /* Every Neon type role is a text-<role> utility with its own line height and
   * weight. lib/utils.ts lists the same roles in cn's font-size group. */
  --text-display1: var(--fontSize-display1); --text-display1--line-height: var(--lineHeight-display1); --text-display1--font-weight: var(--fontWeight-display1);
  --text-display2: var(--fontSize-display2); --text-display2--line-height: var(--lineHeight-display2); --text-display2--font-weight: var(--fontWeight-display2);
  --text-display3: var(--fontSize-display3); --text-display3--line-height: var(--lineHeight-display3); --text-display3--font-weight: var(--fontWeight-display3);
  --text-title1: var(--fontSize-title1); --text-title1--line-height: var(--lineHeight-title1); --text-title1--font-weight: var(--fontWeight-title1);
  --text-title2: var(--fontSize-title2); --text-title2--line-height: var(--lineHeight-title2); --text-title2--font-weight: var(--fontWeight-title2);
  --text-title3: var(--fontSize-title3); --text-title3--line-height: var(--lineHeight-title3); --text-title3--font-weight: var(--fontWeight-title3);
  --text-title4: var(--fontSize-title4); --text-title4--line-height: var(--lineHeight-title4); --text-title4--font-weight: var(--fontWeight-title4);
  --text-headline: var(--fontSize-headline); --text-headline--line-height: var(--lineHeight-headline); --text-headline--font-weight: var(--fontWeight-headline);
  --text-body: var(--fontSize-body); --text-body--line-height: var(--lineHeight-body); --text-body--font-weight: var(--fontWeight-body);
  --text-label1: var(--fontSize-label1); --text-label1--line-height: var(--lineHeight-label1); --text-label1--font-weight: var(--fontWeight-label1);
  --text-label2: var(--fontSize-label2); --text-label2--line-height: var(--lineHeight-label2); --text-label2--font-weight: var(--fontWeight-label2);
  --text-caption: var(--fontSize-caption); --text-caption--line-height: var(--lineHeight-caption); --text-caption--font-weight: var(--fontWeight-caption);
  --text-legal: var(--fontSize-legal); --text-legal--line-height: var(--lineHeight-legal); --text-legal--font-weight: var(--fontWeight-legal);

  --radius-sm: var(--borderRadius-100);
  --radius-md: var(--borderRadius-200);
  --radius-lg: var(--borderRadius-300);
  --radius-xl: var(--borderRadius-400);

  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  /* Neon roles shadcn has no slot for. */
  --color-positive: var(--color-fgPositive);
  --color-warning: var(--color-fgWarning);
  --color-negative: var(--color-fgNegative);
  --color-line-heavy: var(--color-bgLineHeavy);
  --color-inverse: var(--color-bgInverse);
  --color-inverse-foreground: var(--color-fgInverse);
  --color-overlay: var(--color-bgOverlay);
  --color-positive-wash: var(--color-bgPositiveWash);
  --color-warning-wash: var(--color-bgWarningWash);
  --color-negative-wash: var(--color-bgNegativeWash);
  --color-tag-positive: var(--tag-positive);
  --color-tag-warning: var(--tag-warning);
  --color-tag-negative: var(--tag-negative);
  --color-primary-disabled: var(--primary-disabled);
  --color-secondary-disabled: var(--secondary-disabled);
  --color-destructive-disabled: var(--destructive-disabled);
}

:root {
  --background: var(--color-bg);
  --foreground: var(--color-fg);
  --card: var(--color-bgElevation1);
  --card-foreground: var(--color-fg);
  --popover: var(--color-bgElevation2);
  --popover-foreground: var(--color-fg);
  --primary: var(--color-bgPrimary);
  --secondary: var(--color-bgSecondary);
  --secondary-foreground: var(--color-fg);
  --muted: var(--color-bgSecondary);
  --muted-foreground: var(--color-fgMuted);
  --accent: var(--color-bgAlternate);
  --accent-foreground: var(--color-fg);
  --destructive: var(--color-bgNegative);
  --border: var(--color-bgLine);
  /* PROVISIONAL (#97): --input and --ring keep the roles CDS defaults use;
   * the design owner has not confirmed them as Neon roles. */
  --input: var(--color-bgLineHeavy);
  --ring: var(--color-bgLinePrimary);
  /* Text on filled colors (onColorLabel): fgInverse in light. */
  --primary-foreground: var(--color-fgInverse);
  --destructive-foreground: var(--color-fgInverse);
  /* PROVISIONAL (#97): tag inks. fgPositive, fgWarning and fgNegative fail AA
   * on their light washes, so light tags take the darker spectrum shades CDS
   * draws tags in (Green/145, Yellow/170, Red/130), 4.8–6.9:1 on the washes. */
  --tag-positive: rgb(0, 127, 59);
  --tag-warning: rgb(87, 90, 3);
  --tag-negative: rgb(200, 8, 8);
  /* Disabled fills (spike trap 4): CDS blends a filled control's color into the
   * page background at 75%, raised for colors far from the background in
   * luminance (getBlendedColor). The mixes below are that blend worked out for
   * each role; disabled controls also fade to 50% opacity, as in CDS. */
  --primary-disabled: color-mix(in srgb, var(--primary) 93.7%, var(--background));
  --secondary-disabled: color-mix(in srgb, var(--secondary) 75%, var(--background));
  --destructive-disabled: color-mix(in srgb, var(--destructive) 92%, var(--background));
}

/* onColorLabel in dark: filled buttons take fg (white), as createTheme.ts does
 * for CDS. Matches theme.css's own dark selectors.
 * PROVISIONAL (#97): dark tags keep fgPositive and fgWarning (7.5 and 5.5:1 on
 * their washes); fgNegative is 4.25:1, so negative takes Red/50 (8.9:1).
 * PROVISIONAL (#97): white on dark bgNegative measures 4.32:1, below AA. */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --primary-foreground: var(--color-fg);
    --destructive-foreground: var(--color-fg);
    --primary-disabled: color-mix(in srgb, var(--primary) 75%, var(--background));
    --destructive-disabled: color-mix(in srgb, var(--destructive) 75%, var(--background));
    --tag-positive: var(--color-fgPositive);
    --tag-warning: var(--color-fgWarning);
    --tag-negative: rgb(251, 153, 153);
  }
}
:root[data-theme="dark"] {
  --primary-foreground: var(--color-fg);
  --destructive-foreground: var(--color-fg);
  --primary-disabled: color-mix(in srgb, var(--primary) 75%, var(--background));
  --destructive-disabled: color-mix(in srgb, var(--destructive) 75%, var(--background));
  --tag-positive: var(--color-fgPositive);
  --tag-warning: var(--color-fgWarning);
  --tag-negative: rgb(251, 153, 153);
}

@layer base {
  * { @apply border-border outline-ring/50; }
  body { @apply bg-background text-foreground font-sans text-body; }
}
